#!/usr/bin/env python
"""r74_chem_order_mkcond (design seat R74-CHEM-ORDER): generates tools/r74_chem_order_cond.py from R67's
tools/r67_chem_path_cond.py (never edited) by asserted replacements: the worker group_cond(..., M) also returns, for
the M free words of the group with the largest conditional stiffness, the BLOCK of (S_FF + RHO diag)^-1 on them.

    python tools/r74_chem_order_mkcond.py tools/r67_chem_path_cond.py tools/r74_chem_order_cond.py
"""
import sys

src, dst = sys.argv[1], sys.argv[2]
s = open(src, encoding="utf-8").read()


def rep(a, b, n=1):
    global s
    assert s.count(a) == n, (s.count(a), a[:80])
    s = s.replace(a, b)


rep('"""r67_chem_path_cond (design seat R67-CHEM-PATH)',
    '"""r74_chem_order_cond (design seat R74-CHEM-ORDER; generated by tools/r74_chem_order_mkcond.py): a copy of\n'
    'tools/r67_chem_path_cond.py whose worker also returns, for the M free words of the group with the largest conditional\n'
    'stiffness, THE BLOCK Sigma_MM of (S_FF + RHO diag)^-1: the conditional covariance of the next picks, with which the\n'
    'tool decides the words of one stage ONE AFTER THE OTHER (Babai inside the stage: tools/r74_chem_order_fround.py\n'
    '--seq-m M). group_cond(..., M=0) is R67\'s worker unchanged.\n\n'
    'r67_chem_path_cond (design seat R67-CHEM-PATH)')
rep('def cond_of(S, free, rho):\n',
    'def cond_of(S, free, rho, M=0):\n')
rep('    if len(F) == 0:\n        return d\n',
    '    if len(F) == 0:\n        return d if M <= 0 else (d, np.zeros(0, np.int64), np.zeros((0, 0)))\n')
rep('    d[F] = 1.0 / np.diag(inv)\n    return d\n',
    '    d[F] = 1.0 / np.diag(inv)\n'
    '    if M <= 0:\n'
    '        return d\n'
    '    top = np.argsort(-d[F], kind="stable")[:M]          # r74: positions inside F of the M stiffest by d\n'
    '    hi_, lo_ = np.maximum.outer(top, top), np.minimum.outer(top, top)\n'
    '    blk = inv[hi_, lo_]                                  # dpotri filled the lower triangle only\n'
    '    return d, F[top].astype(np.int64), np.ascontiguousarray(blk)\n')
rep('def group_cond(th_g, w_g, K_g, edges, frozen_g, rho, cpu=None):\n',
    'def group_cond(th_g, w_g, K_g, edges, frozen_g, rho, cpu=None, M=0):\n')
rep('    d = cond_of(S, ~np.asarray(frozen_g, bool).reshape(-1), rho)\n'
    '    return d.reshape(frozen_g.shape), sd.reshape(frozen_g.shape)\n',
    '    if M <= 0:\n'
    '        d = cond_of(S, ~np.asarray(frozen_g, bool).reshape(-1), rho)\n'
    '        return d.reshape(frozen_g.shape), sd.reshape(frozen_g.shape)\n'
    '    d, idx, blk = cond_of(S, ~np.asarray(frozen_g, bool).reshape(-1), rho, M)       # r74: + the block of the M stiffest\n'
    '    return d.reshape(frozen_g.shape), sd.reshape(frozen_g.shape), idx, blk\n')
open(dst, "w", encoding="utf-8", newline="\n").write(s)
print("written", dst, len(s))
